#!/usr/bin/env node
/**
 * check-design-fidelity.mjs — Gate 1 of docs/UI-POLISH.md.
 *
 * "Matches the design" is not an opinion here — it is a file. This compares the IMPLEMENTATION
 * (the designsystem theme) against the DESIGN CONTRACT and fails the build on drift.
 *
 *   contract  design/design-contract.json   (versioned; generated by extract-design-contract.mjs
 *                                            from the git-ignored Sage & Gold bundle)
 *   impl      designsystem/.../theme/VastuTheme.kt  +  VastuTypography.kt
 *
 * Checks: the 39 colours · the spacing/radius/elevation/border scales · the type ramp
 * (size, line-height, weight, letter-spacing) · every contrast pair in the design's own audit.
 *
 * Usage:  node scripts/check-design-fidelity.mjs [repoRoot]
 * Exit 0 = conformant · 1 = drift · 2 = a contract input is missing (harness broken — never
 * report "no drift" when the check could not actually run).
 *
 * A deliberate deviation is legal, but it must be declared in ACCEPTED with a reason, so that it
 * shows up in a diff. Silent drift is the whole thing this exists to prevent.
 */
import { readFileSync, existsSync } from 'node:fs';
import { argv, exit } from 'node:process';
import { deriveContract } from './extract-design-contract.mjs';

/* ── declared, reviewed deviations ───────────────────────────────────────────────────────── */
const ACCEPTED = {
  'type.weight.label':
    'Design ramp asks for 600; the bundled DM Sans ships no 600 cut, so label uses Medium (500). ' +
    'Never faux-bold a real face.',
  'radius.radius-full':
    'Design records 999dp; implemented as RoundedCornerShape(percent = 50) — identical for a pill.',
  'color.text-tertiary':
    'Design records #6B7064, which MEASURES 4.39:1 against the card surface #F2EEE4 where WCAG AA ' +
    'requires 4.5 — so every small grey label in the app was below the legibility bar. Implemented ' +
    'as #686C61: same hue and saturation, lightness down three values, 4.64:1 on the card and 4.97 ' +
    'on paper. Still clearly the quietest tier (4.64 against textSecondary 6.90). A contrast floor ' +
    'is not a matter of taste, so the code wins over the swatch here.',
};

/* ── accent colours the design itself audits BELOW their floor ────────────────────────────
 * Not palette bugs — the design marks them "accent". They carry a USAGE CONSTRAINT instead:
 * none may ever be the only thing conveying a meaning (UI-POLISH.md §2.3).                  */
const KNOWN_ACCENTS = new Set(['color-secondary', 'score-workable', 'zone-e']);

const ROOT = argv[2] ?? '.';
const CONTRACT = `${ROOT}/design/design-contract.json`;
const THEME = `${ROOT}/designsystem/src/commonMain/kotlin/com/vastufirst/designsystem/theme/VastuTheme.kt`;
const TYPO = `${ROOT}/designsystem/src/commonMain/kotlin/com/vastufirst/designsystem/theme/VastuTypography.kt`;

for (const [k, f] of Object.entries({ contract: CONTRACT, theme: THEME, typography: TYPO })) {
  if (!existsSync(f)) {
    console.error(`design-fidelity: MISSING INPUT (${k})\n  ${f}`);
    if (k === 'contract') console.error('  Run: node scripts/extract-design-contract.mjs');
    console.error('The harness is broken — refusing to report "no drift".');
    exit(2);
  }
}

const contract = JSON.parse(readFileSync(CONTRACT, 'utf8'));
const themeSrc = readFileSync(THEME, 'utf8');
const typoSrc = readFileSync(TYPO, 'utf8');

const drift = [];
const accepted = [];
const constraints = [];
const fail = (key, msg) => (ACCEPTED[key] ? accepted.push(`${key} — ${ACCEPTED[key]}`) : drift.push(msg));

/* ── 0 · is the committed contract still what the bundle says? ───────────────────────────── */
const live = deriveContract(ROOT);
if (live) {
  const a = JSON.stringify({ ...live, $comment: 0 });
  const b = JSON.stringify({ ...contract, $comment: 0 });
  if (a !== b) {
    drift.push(
      'design/design-contract.json is STALE — the design bundle has changed since it was generated. ' +
      'Run: node scripts/extract-design-contract.mjs',
    );
  }
}

/* ── helpers ─────────────────────────────────────────────────────────────────────────────── */
const camel = (k) => k.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
const FIELD = { zoneNe: 'zoneNE', zoneSe: 'zoneSE', zoneSw: 'zoneSW', zoneNw: 'zoneNW' };
const field = (t) => { const c = camel(t); return FIELD[c] ?? c; };

function colorsFromTheme() {
  const b = themeSrc.match(/val SageGold = VastuColors\(([\s\S]*?)\n\)/);
  if (!b) { drift.push('colour: cannot find `val SageGold = VastuColors(...)`'); return {}; }
  const out = {};
  for (const m of b[1].matchAll(/(\w+)\s*=\s*Color\(0x([0-9A-Fa-f]{8})\)/g)) out[m[1]] = '#' + m[2].slice(2).toUpperCase();
  return out;
}
function dpDefaults(cls) {
  const b = themeSrc.match(new RegExp(`data class ${cls}\\(([\\s\\S]*?)\\n\\)`));
  if (!b) { drift.push(`${cls}: data class not found`); return {}; }
  const out = {};
  for (const m of b[1].matchAll(/val\s+(\w+)\s*:\s*Dp\s*=\s*([\d.]+)\.dp/g)) out[m[1]] = parseFloat(m[2]);
  return out;
}
function shapesFromTheme() {
  const b = themeSrc.match(/data class VastuShapes\(([\s\S]*?)\n\)/);
  if (!b) { drift.push('radius: data class VastuShapes not found'); return {}; }
  const out = {};
  for (const m of b[1].matchAll(/val\s+(\w+)\s*:\s*CornerBasedShape\s*=\s*RoundedCornerShape\(\s*([^)]*?)\s*\)/g)) {
    const dp = m[2].match(/([\d.]+)\.dp/);
    out[m[1]] = dp ? parseFloat(dp[1]) : (/percent\s*=\s*50/.test(m[2]) ? 'full' : m[2]);
  }
  return out;
}
const lum = (hex) => {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map((c) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};
const contrast = (a, b) => { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); };

/* ── 1 · colours ─────────────────────────────────────────────────────────────────────────── */
const impl = colorsFromTheme();
for (const [tok, hex] of Object.entries(contract.color)) {
  const key = field(tok), want = hex.toUpperCase();
  if (!(key in impl)) { fail(`color.${tok}`, `colour ${tok}: no VastuColors field \`${key}\``); continue; }
  if (impl[key] !== want) fail(`color.${tok}`, `colour ${tok}: design ${want}, code ${impl[key]}`);
}

/* ── 2 · spacing ─────────────────────────────────────────────────────────────────────────── */
const spacing = dpDefaults('VastuSpacing');
for (const [tok, v] of Object.entries(contract.space)) {
  const key = tok.replace('space-', 's');
  if (!(key in spacing)) { fail(`space.${tok}`, `spacing ${tok}=${v}dp: no VastuSpacing field \`${key}\``); continue; }
  if (spacing[key] !== v) fail(`space.${tok}`, `spacing ${tok}: design ${v}dp, code ${spacing[key]}dp`);
}

/* ── 3 · radii ───────────────────────────────────────────────────────────────────────────── */
const shapes = shapesFromTheme();
for (const [tok, v] of Object.entries(contract.radius)) {
  const key = tok.replace('radius-', ''), got = shapes[key];
  if (got === undefined) { fail(`radius.${tok}`, `radius ${tok}: no VastuShapes field \`${key}\``); continue; }
  if (v > 100) { if (got !== 'full') fail(`radius.${tok}`, `radius ${tok}: design is a full pill, code ${got}`); }
  else if (got !== v) fail(`radius.${tok}`, `radius ${tok}: design ${v}dp, code ${got}dp`);
}

/* ── 4 · elevation ───────────────────────────────────────────────────────────────────────── */
const elev = dpDefaults('VastuElevation');
for (const [tok, v] of Object.entries(contract.elevation)) {
  const key = tok.replace('elevation-', '');
  if (!(key in elev)) { fail(`elev.${tok}`, `elevation ${tok}: no VastuElevation field \`${key}\``); continue; }
  if (elev[key] !== v) fail(`elev.${tok}`, `elevation ${tok}: design ${v}dp, code ${elev[key]}dp`);
}

/* ── 5 · border widths ───────────────────────────────────────────────────────────────────── */
const borders = dpDefaults('VastuBorders');
const BORDER_FIELD = { hairline: 'hairline', default: 'regular', strong: 'strong', focus: 'focus' };
for (const [tok, v] of Object.entries(contract.border)) {
  const key = BORDER_FIELD[tok.replace('border-', '')];
  if (!key || !(key in borders)) { fail(`border.${tok}`, `border ${tok}: no VastuBorders field`); continue; }
  if (borders[key] !== v) fail(`border.${tok}`, `border ${tok}: design ${v}dp, code ${borders[key]}dp`);
}

/* ── 6 · type ramp ───────────────────────────────────────────────────────────────────────── */
const built = {};
for (const m of typoSrc.matchAll(/(\w+)\s*=\s*style\(\s*([\d.]+)f\s*,\s*"(\w+)"\s*,\s*f\.(\w+)\s*,\s*FontWeight\.(\w+)/g))
  built[m[1]] = { size: parseFloat(m[2]), role: m[3], family: m[4], weight: m[5] };

const mapOfBlock = (name) => {
  const b = typoSrc.match(new RegExp(`private val ${name} = mapOf\\(([\\s\\S]*?)\\)\\n`));
  const out = {};
  if (b) for (const m of b[1].matchAll(/"(\w+)"\s*to\s*([\d.]+)f/g)) out[m[1]] = parseFloat(m[2]);
  return out;
};
const lineHeights = mapOfBlock('LatinLineHeights');
const tracking = mapOfBlock('LatinTracking');
const appliesTracking = /letterSpacing\s*=\s*trackingEm\(/.test(typoSrc);
const W = { Normal: 400, Medium: 500, SemiBold: 600, Bold: 700 };

for (const d of contract.ramp) {
  const name = camel(d.name);
  const b = built[name];
  if (!b) { fail(`type.${name}`, `type: design style "${d.name}" is not built in vastuTypography()`); continue; }
  if (b.size !== d.size) fail(`type.size.${name}`, `type ${d.name}: design ${d.size}sp, code ${b.size}sp`);

  const gotLh = lineHeights[b.role];
  if (gotLh === undefined) fail(`type.lh.${name}`, `type ${d.name}: no line-height for role "${b.role}"`);
  else if (Math.abs(gotLh - d.lineHeight) > 1e-6)
    fail(`type.lh.${name}`, `type ${d.name}: design line-height ${d.lineHeight}, code ${gotLh}`);

  if (W[b.weight] !== d.weight) fail(`type.weight.${name}`, `type ${d.name}: design weight ${d.weight}, code ${W[b.weight]}`);

  if (!appliesTracking) {
    fail(`type.tracking.${name}`, `type ${d.name}: vastuTypography() never applies letterSpacing`);
  } else {
    const gotTr = tracking[b.role];
    if (gotTr === undefined) fail(`type.tracking.${name}`, `type ${d.name}: no LatinTracking entry for role "${b.role}"`);
    else if (Math.abs(gotTr - d.tracking) > 1e-6)
      fail(`type.tracking.${name}`, `type ${d.name}: design letter-spacing ${d.tracking}em, code ${gotTr}em`);
  }
}

/* ── 7 · contrast, against the design's own accessibility audit ──────────────────────────── */
for (const row of contract.contrast) {
  const fg = impl[field(row.fg.replace(/^color-/, ''))];
  const bg = impl[field(row.bg.replace(/^color-/, ''))];
  if (!fg || !bg) continue;
  const r = contrast(fg, bg);
  if (r >= row.floor) continue;
  if (KNOWN_ACCENTS.has(row.fg)) {
    constraints.push(
      `${row.fg} on ${row.bg} = ${r.toFixed(2)}:1 (floor ${row.floor}) — design-declared ACCENT: ` +
      `never let it carry meaning alone; pair with a word, glyph or position. [${row.use}]`,
    );
  } else {
    drift.push(`contrast: ${row.fg} on ${row.bg} = ${r.toFixed(2)}:1, below its ${row.floor}:1 floor (${row.use})`);
  }
}

/* ── report ──────────────────────────────────────────────────────────────────────────────── */
console.log('── design fidelity ────────────────────────────────────────────');
console.log(
  `contract: ${Object.keys(contract.color).length} colours · ${Object.keys(contract.space).length} spacings · ` +
  `${Object.keys(contract.radius).length} radii · ${Object.keys(contract.elevation).length} elevations · ` +
  `${Object.keys(contract.border).length} borders · ${contract.ramp.length} type styles · ` +
  `${contract.contrast.length} contrast pairs`,
);
console.log(live ? 'source: verified against the live design bundle' : 'source: design/design-contract.json (bundle not present — normal in CI)');

if (accepted.length) {
  console.log('\nDECLARED DEVIATIONS (reviewed, allowed):');
  accepted.forEach((a) => console.log('  · ' + a));
}
if (constraints.length) {
  console.log('\nUSAGE CONSTRAINTS (accent colours below their floor by design):');
  constraints.forEach((c) => console.log('  ! ' + c));
}
if (drift.length) {
  console.log(`\n❌ ${drift.length} DRIFT(S) FROM THE DESIGN CONTRACT:`);
  drift.forEach((d) => console.log('  ✗ ' + d));
  console.log('\nFix the code, or — if the deviation is deliberate — add it to ACCEPTED with a reason.');
  exit(1);
}
console.log('\n✅ implementation matches the design contract');
